function evidence = f90_xbatt06_extract_reference_evidence( ...
        modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XBATT06_EXTRACT_REFERENCE_EVIDENCE Replay the exact current reference.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end

assert(isfile(modelPath), "SimuVerity:F90:XBATT06:ModelMissing", ...
    "Reference model is missing: %s", modelPath);
assert(isfile(officialScenarios), "SimuVerity:F90:XBATT06:OfficialScenarios", ...
    "Official scenarios are missing: %s", officialScenarios);
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XBATT06:ReferenceAssetRoot", ...
    "Evaluator-owned reference asset root is missing: %s", evaluatorAssetRoot);

expectedPresence = lower(strtrim(string("present")));
assert(strlength(expectedPresence) > 0, "SimuVerity:F90:XBATT06:ReferenceBinding", ...
    "The evaluator reference file presence binding is missing or invalid.");
assert(localFilePresence(modelPath) == expectedPresence, ...
    "SimuVerity:F90:XBATT06:ReferenceIdentity", ...
    "Reference file presence differs from the task binding.");

referenceRoot = fullfile(evaluatorAssetRoot, "src");
official = localOfficialScenarios(officialScenarios);
localValidateReferenceClosure(referenceRoot, expectedPresence, official);

assert(~isfolder(outputDir), "SimuVerity:F90:XBATT06:OutputReuse", ...
    "Reference evidence output directory already exists: %s", outputDir);
mkdir(outputDir);
cacheDir = fullfile(outputDir, "cache");
codegenDir = fullfile(outputDir, "codegen");
mkdir(cacheDir);
mkdir(codegenDir);
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(referenceRoot, "-begin");
addpath(fullfile(referenceRoot, "data"), "-begin");
addpath(fullfile(referenceRoot, "auxillary"), "-begin");
oldFolder = string(pwd);
folderCleanup = onCleanup(@() cd(oldFolder)); %#ok<NASGU>
cd(referenceRoot);

parameters = load(fullfile(referenceRoot, ...
    "20230919_data_modelparams.mat"));
performance = load(fullfile(referenceRoot, ...
    "20230919_data_performance.mat"));
assert(isfield(parameters, "mp"), "SimuVerity:F90:XBATT06:ModelParameters", ...
    "The native model-parameter evidence is incomplete.");
baseMp = parameters.mp;
assert(isfield(performance, "xhat") && ...
    size(performance.xhat, 1) >= 7 && size(performance.xhat, 2) >= 2, ...
    "SimuVerity:F90:XBATT06:CapacityFit", ...
    "The native capacity-fit evidence is incomplete.");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
scoringRunId = string(getenv("SIMUVERITY_SCORING_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XBATT06:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(strlength(scoringRunId) > 0, "SimuVerity:F90:XBATT06:ScoringRunId", ...
    "SIMUVERITY_SCORING_RUN_ID is required.");

evidencePath = fullfile(outputDir, "evidence.json");
sourcePresenceBefore = localFilePresence(modelPath);
evidence = struct( ...
    "schema", "simuverity.f90-xbatt06-evidence.v1", ...
    "task_id", "F90-XBATT-06", ...
    "evaluation_subject", "reference", ...
    "reference_identity_applicable", true, ...
    "reference_subject", true, ...
    "source_model", modelPath, ...
    "source_model_file_presence", sourcePresenceBefore, ...
    "reference_substantive_modifications", 0, ...
    "runtime_only_noninvasive_changes", true, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "model_closed_without_save", false, ...
    "reference_binding_preserved", false, ...
    "EVIDENCE_COMPLETE", false, ...
    "evidence_complete", false, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "scoring_run_id", scoringRunId, ...
        "matlab_release", string(version("-release")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "temp", string(getenv("TEMP")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));
localWriteJson(evidencePath, evidence);

model = "";
try
    modelHandle = load_system(modelPath);
    model = string(get_param(modelHandle, "Name"));
    assert(model == "BatteryEstim3RC_PTBS_EQ_RUL_v1", ...
        "SimuVerity:F90:XBATT06:ReferenceModelName", ...
        "Unexpected reference model name: %s", model);
    evidence.load_pass = true;
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "off", ...
        "SaveOutput", "on", ...
        "SaveFormat", "Dataset", ...
        "LimitDataPoints", "off");
    firstMp = localScenarioMp(baseMp, performance.xhat, ...
        official.scenarios(1), referenceRoot);
    assignin("base", "mp", firstMp);
    set_param(model + "/Constant", "Value", ...
        sprintf("%.17g", double(official.scenarios(1).temperature_K)));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model, referenceRoot, baseMp);
    localWriteJson(evidencePath, evidence);

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).class = string(scenario.class);
        try
            mp = localScenarioMp(baseMp, performance.xhat, ...
                scenario, referenceRoot);
            rows(k).requested_inputs = struct( ...
                "dataset_index", double(scenario.dataset_index), ...
                "dataset_file", string(scenario.dataset_file), ...
                "temperature_K", double(scenario.temperature_K), ...
                "initial_soc", double(mp.SOC_0), ...
                "available_capacity_Ah", double(mp.CapacityAh), ...
                "initial_charge_deficit_Ah", ...
                    double(mp.InitialChargeDeficitAh), ...
                "forecast_discharge_current_A", ...
                    double(scenario.forecast_discharge_current_A), ...
                "reserve_capacity_Ah", ...
                    double(scenario.reserve_capacity_Ah), ...
                "required_landing_time_s", ...
                    double(scenario.required_landing_time_s));
            assignin("base", "mp", mp);
            set_param(model + "/Constant", "Value", ...
                sprintf("%.17g", double(scenario.temperature_K)));
            set_param(model, "SimulationCommand", "update");
            simIn = Simulink.SimulationInput(model);
            simIn = simIn.setVariable("mp", mp);
            simIn = simIn.setModelParameter( ...
                "StopTime", sprintf("%.17g", mp.t(end)), ...
                "ReturnWorkspaceOutputs", "on");
            started = tic;
            evalc("simOut = sim(simIn);");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut, mp, scenario, ...
                double(official.simulation.output_sample_count));
            rows(k) = localFinalizeScenario(rows(k), outputs, mp);
            clear simOut outputs mp
        catch scenarioException
            rows(k).error = localError(scenarioException);
        end
        evidence.scenarios = rows;
        localWriteJson(evidencePath, evidence);
    end

    evidence.nominal_smoke_pass = rows(1).valid;
    assert(all([rows.valid]), "SimuVerity:F90:XBATT06:ScenarioEvidence", ...
        "One or more fixed reference scenarios did not produce valid evidence.");
    localCloseModel(model);
    evidence.model_closed_without_save = ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    assert(evidence.reference_binding_preserved, ...
        "SimuVerity:F90:XBATT06:ReferenceModified", ...
        "Reference extraction modified the current model file.");
    evidence.EVIDENCE_COMPLETE = evidence.load_pass && ...
        evidence.update_pass && evidence.compile_pass && ...
        evidence.nominal_smoke_pass && ...
        evidence.static_audit.core_path_qualified && ...
        all([evidence.scenarios.valid]) && ...
        evidence.model_closed_without_save && ...
        evidence.reference_binding_preserved;
    evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
    assert(evidence.EVIDENCE_COMPLETE, "SimuVerity:F90:XBATT06:EvidenceIncomplete", ...
        "Reference extraction did not satisfy the evidence-lock prerequisites.");
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
catch sessionException
    try
        if strlength(model) > 0
            feval(model, [], [], [], "term");
        end
    catch
    end
    localCloseModel(model);
    evidence.model_closed_without_save = ...
        strlength(model) == 0 || ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    evidence.EVIDENCE_COMPLETE = false;
    evidence.evidence_complete = false;
    evidence.errors.session = localError(sessionException);
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
    rethrow(sessionException)
end

fprintf("F90_XBATT06_REFERENCE_EVIDENCE load=%d update=%d compile=%d valid=%d/%d complete=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    localValidCount(evidence.scenarios), numel(evidence.scenarios), ...
    evidence.EVIDENCE_COMPLETE, evidencePath);
end

function official = localOfficialScenarios(pathValue)
official = jsondecode(fileread(pathValue));
assert(isstruct(official) && isfield(official, "schema") && ...
    string(official.schema) == "simuverity.official-scenarios.v1", ...
    "SimuVerity:F90:XBATT06:ScenarioSchema", ...
    "Unexpected official scenario schema.");
assert(isfield(official, "task_id") && ...
    string(official.task_id) == "F90-XBATT-06", ...
    "SimuVerity:F90:XBATT06:ScenarioTask", ...
    "Official scenarios are bound to a different task.");
expectedIds = ["nominal_long_flight", "cold_short_high_pulse", ...
    "hot_high_rms_flight", "moderate_profile_high_forecast", ...
    "aged_capacity_long_flight"];
expectedIndices = [1, 2, 3, 6, 7];
expectedFiles = ["2022-07-29 10-38-55_f1.mat", ...
    "2022-08-04 10-58-30_f1.mat", ...
    "2022-08-04 10-58-30_f2.mat", ...
    "2022-09-26 11-49-08_f1.mat", ...
    "2022-10-21 13-31-20_f1.mat"];
actualIds = string({official.scenarios.id});
actualIndices = double([official.scenarios.dataset_index]);
actualFiles = string({official.scenarios.dataset_file});
assert(isequal(actualIds(:).', expectedIds) && ...
    isequal(actualIndices(:).', expectedIndices) && ...
    isequal(actualFiles(:).', expectedFiles), ...
    "SimuVerity:F90:XBATT06:ScenarioContract", ...
    "Official scenario identities or order differ from the task binding.");
requiredFields = ["temperature_K", "forecast_discharge_current_A", ...
    "reserve_capacity_Ah", "required_landing_time_s"];
for k = 1:numel(official.scenarios)
    row = official.scenarios(k);
    for name = requiredFields
        assert(isfield(row, name) && isscalar(row.(name)) && ...
            isfinite(double(row.(name))), ...
            "SimuVerity:F90:XBATT06:ScenarioInput", ...
            "Scenario %s has an invalid %s input.", string(row.id), name);
    end
end
assert(isfield(official, "simulation") && ...
    double(official.simulation.output_sample_count) == 2001 && ...
    logical(official.simulation.retain_full_native_time_coverage), ...
    "SimuVerity:F90:XBATT06:SimulationContract", ...
    "Official simulation settings differ from the task binding.");
end

function localValidateReferenceClosure(referenceRoot, expectedPresence, official)
assert(isfolder(referenceRoot), "SimuVerity:F90:XBATT06:ReferenceClosure", ...
    "Reference dependency root is missing: %s", referenceRoot);
required = [ ...
    fullfile(referenceRoot, "BatteryEstim3RC_PTBS_EQ_RUL_v1.slx"), ...
    fullfile(referenceRoot, "20230919_data_modelparams.mat"), ...
    fullfile(referenceRoot, "20230919_data_performance.mat"), ...
    fullfile(referenceRoot, "test_experimentalDataRUL.m"), ...
    fullfile(referenceRoot, "LICENSE")];
for pathValue = required
    assert(isfile(pathValue), "SimuVerity:F90:XBATT06:ReferenceIncomplete", ...
        "Reference dependency is missing: %s", pathValue);
end
assert(localFilePresence(required(1)) == expectedPresence, ...
    "SimuVerity:F90:XBATT06:ReferenceClosureIdentity", ...
    "Evaluator asset closure contains a different reference model.");
for k = 1:numel(official.scenarios)
    datasetPath = fullfile(referenceRoot, "data", ...
        string(official.scenarios(k).dataset_file));
    assert(isfile(datasetPath), "SimuVerity:F90:XBATT06:ReferenceDataset", ...
        "Reference scenario dataset is missing: %s", datasetPath);
end
end

function mp = localScenarioMp(baseMp, xhat, scenario, referenceRoot)
mp = baseMp;
index = double(scenario.dataset_index);
assert(index >= 1 && index <= numel(mp.fn), ...
    "SimuVerity:F90:XBATT06:DatasetIndex", "Invalid dataset index.");
assert(strcmp(string(mp.fn(index)), string(scenario.dataset_file)), ...
    "SimuVerity:F90:XBATT06:DatasetIdentity", ...
    "Official dataset does not match the pinned native driver list.");
data = load(fullfile(referenceRoot, "data", char(scenario.dataset_file)));
assert(isfield(data, "i") && isfield(data, "v") && isfield(data, "t"), ...
    "SimuVerity:F90:XBATT06:DatasetFields", ...
    "Pinned flight dataset is incomplete.");
mp.j = index;
mp.i = double(data.i(:));
mp.v = double(data.v(:));
mp.t = double(data.t(:));
mp.i(~isfinite(mp.i)) = 0;
valid = isfinite(mp.t) & isfinite(mp.v);
mp.i = mp.i(valid);
mp.v = mp.v(valid);
mp.t = mp.t(valid);
mp.t = mp.t - mp.t(1);
[mp.t, uniqueIndex] = unique(mp.t, "stable");
mp.i = mp.i(uniqueIndex);
mp.v = mp.v(uniqueIndex);
assert(numel(mp.t) >= 100 && mp.t(end) > 100, ...
    "SimuVerity:F90:XBATT06:DatasetDuration", ...
    "Pinned flight dataset is too short.");
mp.Em0 = max(mp.v);
mp.SOC_0 = interp1(mp.Em, mp.SOC_LUT, mp.Em0, "linear", "extrap");
mp.SOC_0 = min(1, max(0, mp.SOC_0));
mp.CapacityAh = double(xhat(index, 1));
mp.CapacityAhPrime = mp.CapacityAh * ones(1, 2);
mp.InitialChargeDeficitAh = double(xhat(index, 2)) * ...
    (1 - mp.SOC_0) * mp.CapacityAh;
mp.itest = mp.i;
mp.tstop = mp.t(end);
mp.PLOT = 0;
end

function outputs = localExtractOutputs(simOut, mp, scenario, sampleCount)
yout = simOut.yout;
assert(isa(yout, "Simulink.SimulationData.Dataset") && ...
    yout.numElements == 4, "SimuVerity:F90:XBATT06:NativeOutputs", ...
    "The pinned model did not return its four native outputs.");
nativeVoltage = localSeries(yout.getElement(1).Values, 1, "plant_voltage");
nativeSoc = localSeries(yout.getElement(2).Values, 1, "plant_soc");
estimatedSoc = localSeries(yout.getElement(3).Values, 1, "estimated_soc");
estimatedVoltage = localSeries(yout.getElement(4).Values, 1, "estimated_voltage");

startTime = max([nativeVoltage.time(1), nativeSoc.time(1), ...
    estimatedSoc.time(1), estimatedVoltage.time(1), mp.t(1)]);
endTime = min([nativeVoltage.time(end), nativeSoc.time(end), ...
    estimatedSoc.time(end), estimatedVoltage.time(end), mp.t(end)]);
assert(endTime > startTime && endTime >= mp.t(end) - 1e-6, ...
    "SimuVerity:F90:XBATT06:Coverage", ...
    "Native outputs do not cover the complete input interval.");
time = linspace(startTime, endTime, sampleCount)';
plantV = localInterp(nativeVoltage, time, "linear");
plantSoc = localInterp(nativeSoc, time, "linear");
estimateSoc = localInterp(estimatedSoc, time, "linear");
estimateV = localInterp(estimatedVoltage, time, "linear");
inputCurrent = interp1(mp.t, mp.i, time, "previous", "extrap");
experimentalV = interp1(mp.t, mp.v, time, "linear", "extrap");

socForParameters = min(max(estimateSoc, min(mp.SOC_LUT)), max(mp.SOC_LUT));
r0 = interp1(mp.SOC_LUT, mp.R0prime, socForParameters, "linear", "extrap");
r1 = interp1(mp.SOC_LUT, mp.R1prime, socForParameters, "linear", "extrap");
r2 = interp1(mp.SOC_LUT, mp.R2prime, socForParameters, "linear", "extrap");
r3 = interp1(mp.SOC_LUT, mp.R3prime, socForParameters, "linear", "extrap");
c1 = interp1(mp.SOC_LUT, mp.C1prime, socForParameters, "linear", "extrap");
c2 = interp1(mp.SOC_LUT, mp.C2prime, socForParameters, "linear", "extrap");
c3 = interp1(mp.SOC_LUT, mp.C3prime, socForParameters, "linear", "extrap");
capacity = mp.CapacityAh * ones(size(time));

consumed = cumtrapz(time, max(inputCurrent, 0)) / 3600;
remaining = max(mp.CapacityAh - mp.InitialChargeDeficitAh - consumed, 0);
usableAfterReserve = max(remaining - ...
    double(scenario.reserve_capacity_Ah), 0);
rul = 3600 * usableAfterReserve / ...
    double(scenario.forecast_discharge_current_A);
safety = rul - double(scenario.required_landing_time_s);

outputs = struct( ...
    "time_s", time, ...
    "battery_input", [inputCurrent, ...
        double(scenario.temperature_K) * ones(size(time))], ...
    "experimental_voltage_V", experimentalV, ...
    "electrical_state", [plantV, estimateV, plantSoc, estimateSoc], ...
    "identified_3rc", [r0, r1, c1, r2, c2, r3, c3, capacity], ...
    "rul_state", [consumed, remaining, rul, safety], ...
    "native_sample_counts", struct( ...
        "plant_voltage", numel(nativeVoltage.time), ...
        "plant_soc", numel(nativeSoc.time), ...
        "estimated_soc", numel(estimatedSoc.time), ...
        "estimated_voltage", numel(estimatedVoltage.time), ...
        "input", numel(mp.t)));
end

function row = localFinalizeScenario(row, outputs, mp)
allValues = [outputs.time_s; outputs.battery_input(:); ...
    outputs.experimental_voltage_V(:); outputs.electrical_state(:); ...
    outputs.identified_3rc(:); outputs.rul_state(:)];
row.simulation_pass = true;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    outputs.time_s(1) == 0 && ...
    outputs.time_s(end) >= mp.t(end) - 1e-6 && ...
    size(outputs.battery_input, 2) == 2 && ...
    size(outputs.electrical_state, 2) == 4 && ...
    size(outputs.identified_3rc, 2) == 8 && ...
    size(outputs.rul_state, 2) == 4;
row.outputs = outputs;
row.metrics = localMetrics(outputs, row.requested_inputs);
row.valid = row.required_evidence_pass && ...
    row.metrics.parameter_positive_fraction == 1 && ...
    row.metrics.time_coverage_fraction >= 0.999999;
row.error = struct;
end

function metrics = localMetrics(outputs, inputs)
t = outputs.time_s;
current = outputs.battery_input(:,1);
experimentalV = outputs.experimental_voltage_V;
electrical = outputs.electrical_state;
parameters = outputs.identified_3rc;
rul = outputs.rul_state;
expectedRul = 3600 * max(rul(:,2) - inputs.reserve_capacity_Ah, 0) / ...
    inputs.forecast_discharge_current_A;
expectedSafety = expectedRul - inputs.required_landing_time_s;
tau = [parameters(:,2).*parameters(:,3), ...
    parameters(:,4).*parameters(:,5), ...
    parameters(:,6).*parameters(:,7)];
metrics = struct( ...
    "time_coverage_fraction", (t(end) - t(1)) / max(t(end), eps), ...
    "experimental_voltage_rmse_V", localRmse(electrical(:,2), experimentalV), ...
    "plant_voltage_rmse_V", localRmse(electrical(:,1), experimentalV), ...
    "plant_estimator_voltage_rmse_V", localRmse(electrical(:,1), electrical(:,2)), ...
    "soc_tracking_rmse", localRmse(electrical(:,3), electrical(:,4)), ...
    "voltage_min_V", min(electrical, [], "all"), ...
    "voltage_max_V", max(electrical(:,1:2), [], "all"), ...
    "soc_min", min(electrical(:,3:4), [], "all"), ...
    "soc_max", max(electrical(:,3:4), [], "all"), ...
    "current_rms_A", rms(current), ...
    "current_peak_A", max(current), ...
    "parameter_positive_fraction", mean(parameters(:,1:7) > 0, "all"), ...
    "tau_min_s", min(tau, [], "all"), ...
    "tau_max_s", max(tau, [], "all"), ...
    "tau_span_ratio", max(median(tau,1)) / min(median(tau,1)), ...
    "consumed_charge_end_Ah", rul(end,1), ...
    "remaining_capacity_start_Ah", rul(1,2), ...
    "remaining_capacity_end_Ah", rul(end,2), ...
    "rul_start_s", rul(1,3), ...
    "rul_end_s", rul(end,3), ...
    "safety_margin_start_s", rul(1,4), ...
    "safety_margin_end_s", rul(end,4), ...
    "rul_identity_max_abs_s", max(abs(rul(:,3) - expectedRul)), ...
    "safety_identity_max_abs_s", max(abs(rul(:,4) - expectedSafety)), ...
    "rul_monotonic_violation_fraction", ...
        mean(diff(rul(:,3)) > 1e-7), ...
    "voltage_dynamic_span_V", max(electrical(:,2)) - min(electrical(:,2)), ...
    "current_voltage_correlation", localCorrelation(current, electrical(:,2)));
end

function audit = localStaticAudit(model, referenceRoot, mp)
plant = model + "/Equivalent Circuit Battery";
estimator = model + "/Estimation Equivalent Circuit Battery/PE 3RC";
current = model + "/Current";
temperature = model + "/Constant";
plantReference = string(get_param(plant, "ReferenceBlock"));
estimatorReference = string(get_param(estimator, "ReferenceBlock"));
currentDestinations = localDestinationBlocks(current, 1);
temperatureDestinations = localDestinationBlocks(temperature, 1);
requiredFields = {'R0prime', 'R1prime', 'C1prime', ...
    'R2prime', 'C2prime', 'R3prime', 'C3prime', ...
    'CapacityAhPrime', 'InitialChargeDeficitAh'};
hasRequiredParameterFields = all(cellfun(@(fieldName) ...
    isfield(mp, fieldName), requiredFields));
nativeOutputs = find_system(model, "SearchDepth", 1, "BlockType", "Outport");
outputNames = string(cellfun(@(x) get_param(x, "Name"), nativeOutputs, ...
    "UniformOutput", false));
audit = struct( ...
    "plant_reference_block", plantReference, ...
    "estimator_reference_block", estimatorReference, ...
    "plant_link_resolved", strcmp(get_param(plant, "LinkStatus"), "resolved"), ...
    "estimator_link_resolved", strcmp(get_param(estimator, "LinkStatus"), "resolved"), ...
    "current_input_connected_to_plant_and_estimator", ...
        any(contains(currentDestinations, "Equivalent Circuit Battery")) && ...
        any(contains(currentDestinations, "Estimation Equivalent Circuit Battery")), ...
    "temperature_input_connected", ...
        any(contains(temperatureDestinations, "Equivalent Circuit Battery")), ...
    "native_output_names", outputNames, ...
    "four_native_outputs_present", numel(nativeOutputs) == 4 && ...
        all(ismember(["V","SOC","SOC1","V1"], outputNames)), ...
    "identified_3rc_parameter_fields_present", ...
        hasRequiredParameterFields, ...
    "driver_present", isfile(fullfile(referenceRoot, ...
        "test_experimentalDataRUL.m")), ...
    "capacity_fit_present", isfile(fullfile(referenceRoot, ...
        "20230919_data_performance.mat")), ...
    "seven_native_flight_datasets_present", ...
        all(arrayfun(@(k) isfile(fullfile(referenceRoot, "data", ...
            char(mp.fn(k)))), 1:numel(mp.fn))) && numel(mp.fn) == 7, ...
    "core_path_qualified", contains(plantReference, ...
        "Equivalent Circuit Battery") && contains(estimatorReference, "PE 3RC") && ...
        hasRequiredParameterFields);
end

function destinations = localDestinationBlocks(block, portIndex)
ports = get_param(block, "PortHandles");
line = get_param(ports.Outport(portIndex), "Line");
if line <= 0
    destinations = strings(0,1);
    return
end
handles = get_param(line, "DstPortHandle");
destinations = strings(numel(handles), 1);
for k = 1:numel(handles)
    destinations(k) = string(get_param(handles(k), "Parent"));
end
end

function series = localSeries(value, channels, name)
assert(isa(value, "timeseries"), "SimuVerity:F90:XBATT06:OutputMissing", ...
    "Required native Timeseries %s is missing.", name);
time = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data,1) ~= numel(time) && size(data,2) == numel(time)
    data = data.';
end
[time, index] = unique(time, "stable");
data = data(index,:);
assert(size(data,1) == numel(time) && size(data,2) == channels && ...
    numel(time) >= 2 && all(isfinite(time)) && all(isfinite(data), "all"), ...
    "SimuVerity:F90:XBATT06:OutputShape", "Invalid native output %s.", name);
series = struct("time", time, "values", data);
end

function values = localInterp(series, time, method)
values = interp1(series.time, series.values, time, method, "extrap");
if isvector(values), values = values(:); end
end

function value = localRmse(a, b)
value = sqrt(mean((a - b).^2));
end

function value = localCorrelation(a, b)
a = a(:); b = b(:);
if std(a) <= eps || std(b) <= eps
    value = 0;
    return
end
matrix = corrcoef(a, b);
value = matrix(1,2);
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "class", "", ...
    "requested_inputs", struct, ...
    "simulation_wall_clock_s", NaN, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "outputs", struct, ...
    "metrics", struct, ...
    "error", struct);
end

function localCloseModel(model)
try
    if strlength(model) > 0 && bdIsLoaded(model)
        close_system(model, 0);
    end
catch
end
end

function count = localValidCount(rows)
if isempty(rows) || ~isfield(rows, "valid")
    count = 0;
else
    count = sum([rows.valid]);
end
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function info = localError(exception)
info = struct("identifier", string(exception.identifier), ...
    "message", string(exception.message), ...
    "report", string(getReport(exception, "extended", "hyperlinks", "off")));
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w");
assert(fid > 0, "SimuVerity:F90:XBATT06:JsonWrite", ...
    "Could not open JSON output: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
